text:
	#waitBackground{
		position:absolute;background-color:rgba(0,0,0,0.4);width:100%;height:100%;
	}
	@media (max-width :420px) {
		body{
			background-position:50%;

		}
		.login-containerT{width:100%!important;

		}
		.mobile-size {
			width:90%!important;
			margin: 0 auto;

		}
		.text-center h3 {
			margin-top: 52px!important;
			font-size: 20px!important;
		}
		.hpanel {
			top:30%;
			margin-top: 20px!important;
			padding: 16px 0 16px 0!important;	

		}
		.sub_text {
			font-size:0.8em!important;			
		}
		#loading3 {
			width:70%!important;
		}
		.main_logo {
			right:50%!important;
			transform: translate(50%)!important;	
		}
		.main_logo img {
			width: 110px!important;
			height: auto!important;
		}
	}
	.login-containerT{max-width:none;width:560px;position:absolute;top:300px;left:50%;transform:translate(-50%,-50%);z-index:99;}

	/* .login-containerT, .row, .col-md-12, .hpanel{margin:0;padding:0;} */
	.login-containerT, .col-md-12, .hpanel{margin:0;padding:0;}
	.panel-bodyT{text-align:center;padding:0px 2it_default.jsp0px 10px!important;border-radius:0;}

	#boxHeadLine{background:#4486d4;width:100%;height:4px;}
	#wait_value{
		color:#1e1e1e;
		font-weight:bold;
		font-size:1.2em;
		margin: 0 0 20px 0;

	}

	#loading3{display:flex;width:50%;justify-content:space-between;margin:30px auto 49px;}
    #loading3>div{width:8px;height:40px;margin-right:7px;background-color:#033074;border-radius: 3px;
        -webkit-animation:strechdelay 1.5s ease-in-out infinite;
        animation:strechdelay 1.5s ease-in-out infinite;
    }
    #loading3 .line2{
        -webkit-animation-delay:-1.4s;
        animation-delay:-1.4s;
    } #loading3 .line3{
        -webkit-animation-delay:-1.3s;
        animation-delay:-1.3s;
    }#loading3 .line4{
        -webkit-animation-delay:-1.2s;
        animation-delay:-1.2s;
    }#loading3 .line5{
        -webkit-animation-delay:-1.1s;
        animation-delay:-1.1s;
    }#loading3 .line6{
        -webkit-animation-delay:-1.0s;
        animation-delay:-1.0s;
    }#loading3 .line7{
        -webkit-animation-delay:-0.9s;
        animation-delay:-0.9s;
    }#loading3 .line8{
        -webkit-animation-delay:-0.8s;
        animation-delay:-0.8s;
    }#loading3 .line9{
        -webkit-animation-delay:-0.7s;
        animation-delay:-0.7s;
    }#loading3 .line10{
        -webkit-animation-delay:-0.6s;
        animation-delay:-0.6s;
    }#loading3 .line11{
        -webkit-animation-delay:-0.5s;
        animation-delay:-0.5s;
    }#loading3 .line12{
        -webkit-animation-delay:-0.4s;
        animation-delay:-0.4s;
    }#loading3 .line13{
        -webkit-animation-delay:-0.3s;
        animation-delay:-0.3s;
    }#loading3 .line14{
        -webkit-animation-delay:-0.2s;
        animation-delay:-0.2s;
    }#loading3 .line15{
        -webkit-animation-delay:-0.1s;
        animation-delay:-0.1s;
    }#loading3 .line16{
        -webkit-animation-delay:-0.0s;
        animation-delay:-0.0s;
    }

    @keyframes strechdelay{
        0%,50%,100%{
            transform:scaleY(.7);
        }
        20%{
            transform:scaleY(1);
            background-color:#2d69c2;
        }
    }

    @-webkit-keyframes strechdelay{
        0%,50%,100%{
            -webkit-transform:scaleY(.7);
        }
        20%{
            -webkit-transform:scaleY(1);
            background-color:#72a5f5;
        }
    }
